// 英語の文の表（events_desert）。key は日本語の表（src/i18n/ja/events_desert.js）と同じ。無い key は日本語が出る
// 差し込み {name} は日本語と同じ名前を残す。数の言い分けは {n, plural, one {…} other {…}}（core/i18n.js）
(function (R) {
  'use strict';
  R.I18n.add('en', {
    // ---- src/events/desert_00_common.js
    'ev.desert_00_common.SONG_BLANK': '♪ O king who called water to the sea of sand,\n♪ your name is -- ...\n♪ in evening prayers forevermore',
    'ev.desert_00_common.SONG_FULL': '♪ O king who called water to the sea of sand,\n♪ your name is Hazar, friend of the sun,\n♪ in evening prayers forevermore',
    'ev.desert_00_common.STARS': ['♪ Nail-star of the north, star that never moves,\n♪ be the stake for caravans gone astray', '♪ Seven spring-stars, tip your dipper,\n♪ scatter the night\'s dew upon the sand', '♪ Star at the world\'s edge, growing pale...\n♪ Grandmother called it "the dawn star"'],
    'ev.desert_00_common.lz.say': ['I broke the seal. The ink had bleached\nto white. "To Mira" -- beyond the name,\nnothing can be read.', '(If a little more light returns,\nI might be able to read it.)'],
    'leads.l_desert_caravan.title': 'Caravan Guard',
    'leads.l_desert_caravan.text': 'Zaid, the caravan master, needs guards\nfor a caravan taking offerings to the Tomb\nOasis. Ask at the Caravan Guild.',
    'leads.l_desert_caravan.from': 'Kasim\'s Caravan Guild',
    'leads.l_desert_spring.title': 'The Failing Spring',
    'leads.l_desert_spring.text': 'Kasim\'s spring is running dry.\nThey say there\'s old, unreadable writing\nat the bottom of it.',
    'leads.l_desert_spring.from': 'Fara, the spring keeper\'s daughter',
    'leads.l_desert_song.title': 'A Song With a Missing Name',
    'leads.l_desert_song.text': 'Nadia the dancer can sing the king\'s\nsong -- all but the king\'s name. Was\nthe name carved in the tomb\'s stones?',
    'leads.l_desert_song.from': 'Nadia the dancer',
    'leads.l_desert_glyphs.title': 'Letters on the Guardian Statues',
    'leads.l_desert_glyphs.text': 'Abul says the king\'s name is carved,\none letter at a time, on the pedestals\nof the tomb\'s guardian statues.',
    'leads.l_desert_glyphs.from': 'Abul, keeper of the tomb',
    'leads.l_desert_tomb.title': 'Deep in the Tomb',
    'leads.l_desert_tomb.text': 'By the old spring at the Tomb Oasis lies\nthe tomb of the Nameless King. The spring\'s\nfire is dying somewhere deep inside.',
    'leads.l_desert_tomb.from': 'The Tomb Oasis',
    'leads.l_desert_hawks.title': 'The Sand Hawks',
    'leads.l_desert_hawks.text': 'Bandits called the "Sand Hawks" rob\nwater on the caravan road. If you hear\na hawk whistle at night, beware.',
    'leads.l_desert_hawks.from': 'Kasim\'s west gatekeeper',
    'leads.l_desert_hawks.dir': 'West',
    'leads.l_desert_sundial.title': 'The Sand-Buried Sundial',
    'leads.l_desert_sundial.text': 'An old sundial in a corner of the square.\nSand from long years has gathered\nin the grooves of its hour marks.',
    'leads.l_desert_sundial.from': 'The sundial grandpa',
    'leads.q_kasim_anklet.title': 'The Dancer\'s Anklet Bell',
    'leads.q_kasim_anklet.text': 'Nadia lost her silver anklet bell.\nA market child seems to have found it,\nbut won\'t give it back for nothing.',
    'leads.q_kasim_anklet.from': 'Nadia the dancer',
    'leads.q_kasim_dig.title': 'Helping the Well-Digger',
    'leads.q_kasim_dig.text': 'Omar, the master well-digger, wants\nthree spots dug in the sand outside town,\nto find where the water runs.',
    'leads.q_kasim_dig.from': 'Master well-digger',
    'leads.q_kasim_camel.title': 'The Lost Camel',
    'leads.q_kasim_camel.text': 'One of the guild\'s camels wandered\noff into the dunes. Someone saw it\nin the dunes to the southeast.',
    'leads.q_kasim_camel.from': 'Caravan Guild counter',
    'leads.q_kasim_camel.dir': 'Southeast',
    'leads.q_kasim_beacons.title': 'Signal Fires on the Caravan Road',
    'leads.q_kasim_beacons.text': 'Three signal towers on the caravan road\nhave gone dark. Bring oil from the black\nspring, and they can be lit again.',
    'leads.q_kasim_beacons.from': 'Tadeo of the Lampkeepers\' Guild',
    'leads.q_kasim_beacons.dir': 'West',
    'leads.q_kasim_salt.title': 'Salt for the Waystation',
    'leads.q_kasim_salt.text': 'Karim the salt seller asked me to deliver\na parcel of salt to Lotta the peddler\nat the Sandedge waystation.',
    'leads.q_kasim_salt.from': 'Karim the salt seller',
    'leads.q_kasim_salt.dir': 'North',
    'leads.q_kasim_maps.title': 'The Mapmaker\'s Treasure Maps',
    'leads.q_kasim_maps.text': 'Yaz the mapmaker sells old treasure maps.\nEach time a Beacon returns, it seems,\nmore of them become readable.',
    'leads.q_kasim_maps.from': 'Yaz the mapmaker',
    'leads.l_opt_sandedge.title': 'The Inn at the Crossroads',
    'leads.l_opt_sandedge.text': 'Where the roads of forest, desert, and ash\nmeet stands the waystation of Sandedge.\nIts spring water is sweet, they say.',
    'leads.l_opt_sandedge.from': 'Guest at Kasim\'s inn',
    'leads.l_opt_sandedge.dir': 'North',
    'leads.l_opt_mirage.title': 'The Mirage Market',
    'leads.l_opt_mirage.text': 'Only at lights-out, they say, rows of\nlamps and the bustle of a market\nshimmer in the middle of the sand.',
    'leads.l_opt_mirage.from': 'Landlady of Kasim\'s inn',
    'leads.l_opt_mirage.dir': 'Southwest',
    'leads.l_opt_temple.title': 'The Beach of Sunken Pillars',
    'leads.l_opt_temple.text': 'The tops of strange pillars poke out of\nthe sand on the southern beach. On\nfull-moon nights, there are more.',
    'leads.l_opt_temple.from': 'Sunburned man',
    'leads.l_opt_temple.dir': 'South',
    'leads.l_opt_rocks.title': 'Moving Rocks',
    'leads.l_opt_rocks.text': 'Caravaners say a rock moved in the rocky\nground to the north. Its scales shone\nall the colors of the rainbow.',
    'leads.l_opt_rocks.from': 'Kasim\'s tavern',
    'leads.l_opt_rocks.dir': 'North',
    'leads.l_opt_hawknest.title': 'Hawk Whistles on the Mesa',
    'leads.l_opt_hawknest.text': 'Every night, hawk whistles are heard\nfrom the rocky mesa west of town.\nIt could be the Sand Hawks\' roost.',
    'leads.l_opt_hawknest.from': 'Kasim\'s gatekeeper',
    'leads.l_opt_hawknest.dir': 'West',
    'leads.l_tmap_3.title': 'Treasure Map No. 3',
    'leads.l_tmap_3.text': 'The Broken Sword Monument in the Ashen\nWastes. Behind the sealed door on the lower\nlevel lies a treasure with a quill crest.',
    'leads.l_tmap_3.from': 'Treasure Map No. 3',
    'leads.l_tmap_3.dir': 'Southeast',
    'leads.l_tmap_5.title': 'Treasure Map No. 5',
    'leads.l_tmap_5.text': 'The ship graveyard of a hundred masts,\nin the fog of the western sea. A sealed door\nin the hold of the ship with the third mast.',
    'leads.l_tmap_5.from': 'Treasure Map No. 5',
    'leads.l_tmap_5.dir': 'Western sea',
    'leads.l_tmap_6.title': 'Treasure Map No. 6',
    'leads.l_tmap_6.text': 'A map smudged beyond reading.\nWith a star fragment, they say,\nit could be read.',
    'leads.l_tmap_6.from': 'Treasure Map No. 6',
    'leads.l_tmap_6.dir': '?',
    'leads.l_main_recorder_desert.title': 'Traces of a Rubbing',
    'leads.l_main_recorder_desert.from': 'The king\'s chamber in the tomb',
    'leads.l_main_recorder_desert.text': 'Paper fibers and ink on the king\'s chamber\nwall. "Archive Copy No. 82." The name left\nthe stone only after it was copied.',
    'leads.l_main_margin_named.title': 'The Night I Called His Name',
    'leads.l_main_margin_named.from': 'The Clue Journal\'s margin',
    'leads.l_main_margin_named.text': 'Called by his name, the king could sleep.\n...Perhaps names are also\nmeant for rest.',
    'lore.lo_ev_desert.title': 'Traces of a Rubbing',
    'lore.lo_ev_desert.text': 'Paper fibers and ink on the stone tablet\nin the king\'s chamber. A tag lay in the sand:\n"Archive Copy No. 82."',
    'lore.lo_time_desert.title': 'The Sand-Buried Sundial',
    'lore.lo_time_desert.text': 'Twenty years of sand in the grooves of its\nhour marks. The guild ledger\'s "Sunrise Prayer"\ncolumn ends in winter, Lumen Year 292.',
    'lore.lo_war_desert.title': 'The Monument With Worn Names',
    'lore.lo_war_desert.text': 'The Sun Alliance\'s war memorial at Rock Well.\nThe wind has worn every name away.\nOn its back: "The Sun is the King\'s Fire."',
    'lore.lo_desert_spring_letters.title': 'Old Letters at the Spring\'s Bottom',
    'lore.lo_desert_spring_letters.text': 'Old writing on a stone at the bottom of the\ndry spring: "...\'s fire, entrusted to the spring.\nWhile the name is called, the fire shall not die."',
    'lore.lo_desert_camp_notes.title': 'Notes From an Earlier Caravan',
    'lore.lo_desert_camp_notes.text': 'A scrap of board at an old campsite:\n"Stormy night. A row of lights toward the tomb.\nThey vanished as we neared. A market\'s voices."',
    'ev.desert_00_common.LZ.2': ['Mira. The child we kept at your house\nhas taken his first steps.', 'I will not speak to him\nof his mother.', 'So that the storytellers\' songs\ndo not carry him away, too.'],
    'ev.desert_00_common.LZ.3': ['Mira. I have copied your face.\nBecause every morning (no -- there\nare no more mornings), remembering hurts.', 'I will leave the portrait hanging.\nWhat it is a picture of,\nI no longer know.'],
    'ev.desert_00_common.LZ.4': ['Mira. The voice in the book\nhas grown louder of late.\n"You wish to forget, don\'t you?"', 'I do wish to forget. And yet\nI do not want to lose you.\nBoth are true.'],
    'ev.desert_00_common.LZ.5': ['Mira. People who wish to cast off\ntheir names have begun to come\nto the Archive.', 'I did not turn them away.\nI know how heavy\na name can be.'],
    'ev.desert_00_common.LZ.6': ['Mira. Biblia is turning white.\nThe copyists forget\nwhat they have copied.', 'In time, so shall I.\nThat is my mercy.'],
    'ev.desert_00_common.LZ.7': ['Mira. I did not want anyone to wake\nto a morning without their child.', 'That is all\nI did.'],
    'ev.desert_00_common.LZ.8': ['Mira. The book says to me:\ncopy the eight legends, too.', 'Then no one need ever\nlose anything again.', '...Mira. What would you say?\nI can no longer remember\nyour voice.'],
    'ev.desert_00_common.letters.from': '(No sender\'s name)',
    'ev.desert_00_common.letters.title': 'A Letter Never Burned',
    'ev.desert_00_common.lore.title': 'A Letter Never Burned',
    'ev.desert_00_common.lore.text': 'A letter left behind by a Recorder.\nAddressed "To Mira." No sender\'s name.',
    'letters.letter_desert_nadia.from': 'Nadia',
    'letters.letter_desert_nadia.title': 'The King\'s Song (a copy)',
    'letters.letter_desert_nadia.text': ['O king who called water to the sea of sand,\nyour name is Hazar, friend of the sun,\nin evening prayers forevermore', '(Small, in the corner)\nThis time I won\'t forget the name.\nI\'ll write it, sing it, and write it again.'],
    'chronicle.r_desert.title': 'The King Who Sold His Name',
    'chronicle.r_desert.parts.0.text': 'In the year the oasis spring ran low,\nthe apprentice storyteller guarded a caravan\nthrough three nights in the desert.',
    'chronicle.r_desert.parts.1.text': 'At Rock Well, blades were crossed with the Sand Hawks.',
    'chronicle.r_desert.parts.2.text': 'At Rock Well, water was shared with the Sand Hawks.',
    'chronicle.r_desert.parts.3.text': 'At Rock Well, the Sand Hawks were paid their toll.',
    'chronicle.r_desert.parts.4.text': 'Through the sandstorm hollow, the stars showed the way.',
    'chronicle.r_desert.parts.5.text': 'Avoiding the storm, they took the long way round by the western beach.',
    'chronicle.r_desert.parts.6.text': 'In the king\'s chamber, in the midst of battle, the apprentice called the king\'s name.',
    'chronicle.r_desert.parts.7.text': 'Bandits called the Sand Hawks attacked the caravan,\nand the king took back his name.',
    'chronicle.r_desert.parts.8.text': 'The Sand Hawks were once soldiers who fought\nfor the king\'s fire.\nNo one remembers what the war was for.',
    'chronicle.r_desert.parts.9.text': 'At the bottom of the old spring, the sun-fire was lit.',
    // ---- src/events/desert_caravan.js
    'ev.desert_caravan.ZAID.name': 'Zaid',
    'ev.desert_caravan.RASHID.name': 'Rashid',
    'events.desert_caravan_depart.caption': 'One cart, two camels.\nZaid\'s caravan fell in\nbehind the party.',
    'events.desert_caravan_depart.say': ['The first camp is "Rock Well."\nOut the west gate, then south along the road.', 'While we travel together, monsters\nwill be drawn to us more easily.\n...I\'m counting on you.'],
    'ev.desert_caravan.AMBUSH.1.text': 'The sand beneath the cart stirs!\nSand scorpions sink their claws into the cargo!',
    'ev.desert_caravan.AMBUSH.2.text': 'A camel shrieks and stops dead.\nSomething\'s coming up out of the sand!',
    'ev.desert_caravan.AMBUSH.3.text': 'Under the starlight, shadow after shadow\ncrawls across the sand.\nThey mean to surround the caravan!',
    'ev.desert_caravan.say': 'Protect the cargo! Whatever happens,\ndon\'t let them break the water jars!',
    'ev.desert_caravan.say_2': 'Pull the camels back!\n...Please, get up front!',
    'ev.desert_caravan.say_3': 'Cut through before\nthey surround us!',
    'ev.desert_caravan.say.0': '...That was close. Cargo and water are safe.',
    'ev.desert_caravan.say.1': 'The oasis isn\'t far now.',
    'ev.desert_caravan.say.1_2': 'Come on, just a little further\nto camp.',
    'ev.desert_caravan.starSong.caption': ['The campfire crackles.\nZaid looks up at the stars and begins to sing.', 'The caravan folk sit in a ring\naround the campfire. Zaid sings.', 'By the oasis spring, the campfire of\nthe third night. Zaid sings.'],
    'events.desert_camp1_scene.caption': 'An old well ringed by rocks.\nThe marks of many old campfires remain.',
    'events.desert_camp1_scene.say': ['The northern nail-star\'s always in the same\nplace. So long as you can see it, a\ncaravan won\'t lose its way.', '...Mind you, caravans long ago read the road\nby "where the sun goes down," they say.\nWhatever the sun was.'],
    'events.desert_camp1_scene.caption_2': 'When the fire had burned low --\na hawk whistle sounded from atop the rocks.',
    'events.desert_camp1_scene.say_2': 'Men with cloth-wrapped faces are\naiming bows from atop the rocks.',
    'events.desert_camp1_scene.say_3': ['Don\'t move. We won\'t take your lives.', 'We are the "Sand Hawks."\nIt\'s water we want. Leave\nhalf your water jars.'],
    'events.desert_camp1_scene.say_4': '...Half?! Then we\'ll never\nmake it to the oasis!',
    'events.desert_camp1_scene.i.choose.0': 'Fight',
    'events.desert_camp1_scene.i.choose.1': 'Share the water',
    'events.desert_camp1_scene.i.choose.2': 'Pay them ({price} G)',
    'events.desert_camp1_scene.i.choose.text': 'What will you do about the Sand Hawks?',
    'events.desert_camp1_scene.say_5': '...So be it. Then let the sand decide.',
    'events.desert_camp1_scene.say_6': 'The masked man fell to one knee\nand drove his scimitar into the sand.',
    'events.desert_camp1_scene.say_7': ['...Good arm. I\'m Rashid.\nI was a soldier of the Sun Alliance, once.', 'Twenty years ago, the night of the\nchampions\' bout... I heard singing.\nFriend and foe alike stopped.', '...What happened after, I somehow\ncan\'t recall. Next thing I knew,\nI was a bandit on the sand.', 'Go. We\'re heading back to the mesa caves.\n...Next time, it won\'t go like this.'],
    'events.desert_camp1_scene.say_8': '...All right. Our lives are worth more.\nTake half.',
    'events.desert_camp1_scene.say_9': ['...Sorry. There are children and\nold folk back in the caves.', 'Mind if I sit by your fire?\nI feel like talking a while.'],
    'events.desert_camp1_scene.say_10': 'The masked man gave his name as Rashid\nand sat down by the campfire.',
    'events.desert_camp1_scene.say_11': 'Not enough money...',
    'events.desert_camp1_scene.say_12': '...No help for it.\nGive them half the water.',
    'events.desert_camp1_scene.say_13': '...Sorry about this. There are children\nand old folk back in the caves.',
    'events.desert_camp1_scene.say_14': ['...Money, eh. You can\'t buy water\nin the desert, but you can in town.', 'You may pass. I\'m Rashid.\nIf you ever come to the mesa caves,\nI\'ll at least hear you out.'],
    'events.desert_camp1_scene.caption_3': 'A short sleep by the campfire.\n(The party\'s HP and MP were restored.)',
    'events.desert_camp1_scene.say_15': ['Next camp is "Star Stone."\nSouth from here, along the road.', '...I\'ll write tonight down properly\nin the guild ledger.'],
    'events.desert_rashid_fire.say': ['...We\'re what\'s left of the deserters\nfrom the Sun Alliance.', 'Twenty years ago, the night of the\nchampions\' bout. I heard singing.\nFriend and foe alike stopped.', 'What happened after...\nsomehow, I can\'t recall.\nNot even what the war was for.'],
    'events.desert_rashid_fire.say_2': 'The money will buy medicine for the\npeople in the caves. ...Don\'t expect thanks.',
    'events.desert_rashid_fire.say_3': 'For the water: come to the mesa caves,\nand we\'ll welcome you as one of us.\n...That much, I promise.',
    'events.desert_rashid_fire.say_4': 'This well used to overflow\nwith water too, they say.\n...When the spring\'s fire weakens, wells dry up.',
    'events.desert_camp2_scene.caption': 'A standing stone carved with stars\nrises alone from the sand.',
    'events.desert_camp2_scene.say': ['The water jars are light.\nEveryone in the caravan could\nonly drink a mouthful.', 'The party is thirsty...\n(MP decreased slightly.)'],
    'events.desert_camp2_scene.say_2': 'The seven spring-stars make a dipper.\nGrandmother called them "the stars\nthat scatter the night\'s dew."',
    'events.desert_camp2_scene.caption_2': 'The northern sky turned a muddy brown.\nThe wind began to whip up the sand.',
    'events.desert_camp2_scene.say_3': ['A sandstorm. ...There are two ways.', 'A shortcut straight through the northern\nhollow -- right into the storm. Plenty of\nmonsters, but an old caravan camp too.', 'Or the long way round by the western beach.\nSafe, but long. There\'s an old\nwell hut on the way.'],
    'events.desert_camp2_scene.i.choose': ['Shortcut (through the sandstorm hollow)', 'Long way (around by the western beach)'],
    'events.desert_camp2_scene.i.choose.text': 'Which way will you go?',
    'events.desert_camp2_scene.say_4': ['Right, I\'ll clear the sand from the\nhollow\'s southern mouth.', 'North from Star Stone. Once through the\nhollow, the Tomb Oasis is close.'],
    'events.desert_camp2_scene.say_5': ['Careful, eh. ...I don\'t mind that.', 'West from Star Stone, then north once\nwe reach the beach. We\'ll top up\nour water at the well hut.'],
    'events.desert_camp2_scene.caption_3': 'A short sleep to the sound of the storm.\n(The party\'s HP and MP were restored.)',
    'events.desert_camp2_saddlebag.say': 'An old saddlebag, half buried in\nthe sand. Nothing\'s left inside.',
    'events.desert_camp2_saddlebag.say_2': ['An old saddlebag, half buried in the sand.\nA quill mark is branded into the leather.', 'Inside, a single letter remains,\nits seal unbroken.'],
    'events.desert_camp2_stone.say': ['A standing stone carved with stars.\nThe northern nail-star, the seven spring-stars.', 'At the very bottom, a round mark\nbigger than the rest is carved.\nToo big to be a star.'],
    'events.desert_camp2_stone.say_2': '...Rays of light are carved around\nthe round mark, as if\nit were burning.',
    'events.desert_camp2_child.say': 'The big circle at the bottom of the Star Stone?\nGrandpa calls it "the sun-wheel."\n...He says it used to be in the sky.',
    'events.desert_camp2_child.say_2': ['I\'m a star-reader\'s apprentice.\nI learn the stars\' names at the Star Stone.', 'You know, in the northern hollow, on stormy\nnights, you can see an old caravan camp.\nGrandpa says there\'s treasure there.'],
    'events.desert_camp3_scene.caption': 'By the old spring, the entrance to a tomb\ncut into the sandstone cliff.\n...The entrance is blocked with sand.',
    'events.desert_camp3_scene.caption_2': 'The Tomb Oasis.\nThe old spring had grown so shallow\nits bottom stones showed.',
    'events.desert_camp3_scene.say': ['The star at the world\'s edge, growing pale...\nMy grandmother called that one\n"the dawn star."', '...Dawn.\nStrange word.\nNight... breaks? What breaks?'],
    'events.desert_camp3_scene.say_2': 'Zaid tilted his head and added\nwood to the fire.',
    'events.desert_camp3_scene.say_3': ['The offerings are laid by the spring.\nThe caravan will wait here.', 'My people cleared the sand from the tomb\nentrance. ...From here on, it\'s just you.', 'Old Abul, the tomb keeper, should have\ncome by the old road too.\nHear what he has to say.'],
    'events.desert_camp3_scene.caption_3': 'A short sleep by the spring.\n(The party\'s HP and MP were restored.)',
    'events.desert_camp_zaid.say': 'Something changed deep in the tomb.\nThe bottom of the spring... it\'s warm.',
    'events.desert_camp_zaid.say_2': ['The caravan\'s waiting by the spring.\nNo need to hurry. ...But come\nback safe.', 'The king\'s name...\nOur prayers have no place for\na name. They never have.'],
    'events.desert_camp_zaid.say_3': 'The hollow is north. In the storm,\ndon\'t lose track of the Star Stone.',
    'events.desert_camp_zaid.say_4': 'Out to the western beach, then north.\nWe\'ll rest at the well hut.',
    'events.desert_camp_zaid.say_5': 'Next is "Star Stone." South along the road.\n...The stars are clear tonight.',
    'events.desert_camp_man.say': 'The camels are drinking this water\nlike it\'s the best they\'ve had.\n...Shallow, though.',
    'events.desert_camp_man.say_2': 'I\'ve never been inside the tomb.\nThey say those who\'ve forgotten\ntheir names never come out, right?',
    'events.desert_camp_man.say.fight': 'That Hawk leader was strong...\nGlad you were with us.',
    'events.desert_camp_man.say.water': 'Less water, but nobody died.\n...I say that\'s fine.',
    'events.desert_camp_man.say.pay': 'If money settles it, that\'s best.\nIn the guild ledger, it\'s a "toll."',
    'events.desert_camp_man.say_3': 'The Hawks, eh...',
    'events.desert_camp_man.say_4': 'I can smell a sandstorm.\nIt tickles the back of my nose.',
    'events.desert_camp_man.say_5': 'I\'m Fad. I mind the cart.\nIf a wheel sticks in the sand,\nhelp me push, will you?',
    'events.desert_camp_man.say_6': 'I\'m Samir. Night watch.\nThey say bandits show up\naround Rock Well.',
    'events.desert_camp1_well.say.0': 'An old well ringed by rocks.\nLower a rope, and there\'s no sound of water.',
    'events.desert_camp1_well.say.1': '...No -- far down, water\nglints faintly.',
    'events.desert_camp1_well.say.1_2': 'The sand at the bottom is bone-dry.',
    'events.desert_camp1_memorial.say': ['A stone monument worn by the wind,\ncarved with the sun-wheel crest.', 'The names of soldiers killed in the war\nwere listed here, it seems... but\nnot one can be read.'],
    'events.desert_camp1_memorial.say_2': 'In the corner of the monument, several\nnewly carved names are lined up.\nCut carefully, with a blade.',
    'events.desert_camp1_old.say': 'Water\'s starting to come back into the well.\n...To think I\'d live to see it.',
    'events.desert_camp1_old.say_2': ['I\'m the keeper of this well.\nNo water, but a keeper\'s a keeper.', 'That monument? From the war twenty years back.\nThe wind took the names away.\n...Nobody knows now who died.'],
    // ---- src/events/desert_kasim.js
    'events.kasim_arrival.caption': 'Kasim, the oasis town.\nA town at the feet of a faceless\nking\'s colossus, half-buried in the dunes.',
    'events.kasim_arrival.caption_2': 'Half the market stalls before\nthe colossus had lowered their awnings.',
    'events.kasim_arrival.caption_3': 'The caravans can\'t set out, and goods\ndon\'t arrive. The spring\'s water,\ntoo, dwindles by the day.',
    'events.kasim_arrival.caption_4': 'The spring\'s surface reflects a golden fire.\nEvery last stall in the market\nhas raised its awning.',
    'events.kasim_fara.say': ['I read the writing at the spring\'s bottom\nevery night. "While the name is called,\nthe fire shall not die."', 'The Beacons in other lands must\nburn by someone\'s name, too.'],
    'events.kasim_fara.say_2': ['The spring\'s back!\nFather was crying\nas he drew the water.', 'I finally understand the writing.\nWhile the name is called,\nthe fire won\'t die.'],
    'events.kasim_fara.say_3': ['I\'m Fara. My father is\nthe keeper of this spring.', 'Every year the spring gets a little\nshallower. This year, at last,\nyou can see the bottom.', 'There\'s old writing carved on the bottom stone.\nNo one can read it... but have a look\nbetween the fingers of the stone hand.'],
    'events.kasim_fara.say_4': ['"While the name is called, the fire\nshall not die"...?', 'The old spring by the tomb is where this\nspring\'s water comes from, they say.\nMaybe there\'s something there too.'],
    'events.kasim_fara.say_5': 'Did you see the writing at the bottom?\nYou can peek at it between\nthe stone hand\'s fingers.',
    'events.kasim_spring_letters.say': ['The old writing at the spring\'s bottom\nglows gold beneath the water.', '"Hazar\'s fire, entrusted to the spring.\nWhile the name is called, the fire shall not die."'],
    'events.kasim_spring_letters.say_2': ['Between the fingers of the stone hand,\nyou peer down at the dry spring bed.\nOld writing is carved on the bottom stone.', '"...\'s fire, entrusted to the spring.\nWhile the name is called,\nthe fire shall not die."', 'Only the very beginning has\nworn away completely.'],
    'events.kasim_sundial.say': ['An old sundial in the corner of the square.\nIts shadow-casting needle points at the sky.', 'The grooves of its hour marks\nare packed with sand. How many years\'...\nno, how many decades\' worth?'],
    'events.kasim_sundial.say_2': '...A sundial that casts no shadow.\nHow long has it gone unused?',
    'events.kasim_colossus.say': ['The colossus\'s pedestal. A procession of\ncaravans leading camels is carved in relief.', 'Only the frame in the middle, where a name\nwould go, has been chiseled away. The face\nabove is worn smooth by the wind.'],
    'events.kasim_colossus.say_2': 'Beneath the chiseled frame, someone\nhas carved in small letters:\n"Hazar."',
    'events.kasim_colossus.say_3': '...According to Abul, the king\'s name\nhad vanished from the stones of\nthe tomb as well.',
    'events.kasim_guild_ledger.say': ['An old ledger of the Caravan Guild.\nIt has a column headed "Sunrise Prayer."', 'A mark for the prayer said each morning\nbefore a caravan left, it seems. ...The marks\nend in winter, Lumen Year 292.'],
    'events.kasim_guild_ledger.say_2': 'Winter, twenty years ago...\nCould it have to do with the sundial\nin the market?',
    'events.kasim_old_man.say': ['The sun-fire is a piece of the sun.\nI still believe that.', '...But King Hazar didn\'t take it from\nthe sky. He traded his name for it.'],
    'events.kasim_old_man.say_2': ['This sundial, now -- it\'s been here since\nmy grandfather\'s grandfather\'s day.', 'But when I was young, after one\nparticular winter, it stopped\ncasting a shadow. Just like that.', 'A tool for telling time that casts no\nshadow... Makes you laugh, eh?\nNobody sweeps the sand out anymore.'],
    'events.kasim_board': '"Guards wanted. A caravan carrying offerings\nto the Tomb Oasis. Those handy with a blade,\nsee Zaid at the Caravan Guild."',
    'events.kasim_board_2': '"The caravan has reached the Tomb Oasis.\nIt waits by the spring."',
    'events.kasim_board_3': '"Rejoice! The spring\'s water has returned.\nTonight we sing the king\'s song in the square.\n-- The Caravan Guild"',
    'events.kasim_board_4': '"The lost camel is back. Thank you."',
    'events.kasim_board_5': '"One guild camel lost.\nFinders, please come to the counter."',
    'events.kasim_board_6': '"Furs arrived from the northern snowfields.\nThe pass south to the Ashen Wastes is closed\ndue to a collapse."',
    'events.kasim_memorial.say': ['The Sun Alliance\'s war memorial.\nBeside the worn names, many new names\nhave been carved again.', 'Carefully, with a blade.\nThe Sand Hawks\' work, no doubt.'],
    'events.kasim_memorial.say_2': ['The Sun Alliance\'s war memorial.\nCarved on it: "The Sun is the King\'s Fire."', 'After twenty years of sandy wind,\nthe names are all but unreadable.'],
    'events.kasim_well.say': 'The town well. The water has risen\nalmost to within arm\'s reach.',
    'events.kasim_well.say_2': ['The town well. You lower the bucket, and\nafter a long, long time comes\nthe faint sound of water.', 'A sign hangs on it:\n"Ten gold a cup."'],
    'events.kasim_hawk_friend.say': ['I gather salt down on the south beach.\n...Saw something odd, I did.', 'The night after a sandstorm cleared, on the\nmoonlit beach, the tops of pillars I\'d never\nseen were sticking out of the sand.', 'Next night, they were under the sand again.\nMaybe you only see \'em at lights-out,\non a full-moon night.'],
    'events.kasim_hawk_friend.say_2': ['You tangled with the Sand Hawks? They\'ve\ngone back to their caves and dug in, I hear.', 'Their leader hides behind his archers.\nShut the archers up first, and the\nleader\'s guard drops, they say.'],
    'events.kasim_hawk_friend.say_3': ['You talked with the Hawks\' leader?\n...They\'re not rotten to the core,\nthat lot.', 'There are old folk and kids in\nthe mesa caves. Drop by sometime,\nif you feel like it.'],
    'events.kasim_gate_w.say': 'The signal fires are coming back\non the caravan road. Patrols are easier now.',
    'events.kasim_gate_w.say_2': ['Out the west gate and south is the caravan road.\nThree nights to the Tomb Oasis.', 'Be careful. Bandits called the "Sand Hawks"\nprowl the caravan road. If you hear\na hawk whistle at night, beware.', 'Their leader kicks up sand, then comes\nat you with a big slash.\nWhen the sand flies, guard yourself.'],
    'events.kasim_gate_w.say_3': ['You met the Sand Hawks?\n...Glad you\'re in one piece.', 'Every night, hawk whistles come from\nthe rocky mesa to the west.\nThat must be their roost.'],
    'events.kasim_gate_e.say': ['Past the east gate is the pass to the\nAshen Wastes. ...But an ash slide blocks it.', 'Over in Caldera, the firebird\'s egg is\ngrowing cold, they say. An ash-covered\ntraveler told me so.'],
    'events.kasim_water_woman.say.0': 'To celebrate the spring coming back!\nHave a cup. ...Free!',
    'events.kasim_water_woman.say': ['I\'m Malika, the water seller.\nThe spring\'s water keeps dwindling.', '...Oh, a traveler? You must be thirsty.\nI\'ll give you one cup on the house.'],
    'events.kasim_water_woman.say_2': 'The price of water\'s been halved.\nBad for business, but everyone\'s\nsmiling, so it\'s fine by me.',
    'events.kasim_water_woman.say_3': 'If the spring dries up, the town is finished.\n...So every night I pray\nit won\'t come to that.',
    'events.kasim_kid.say': 'I swam in the spring\nand got scolded!',
    'events.kasim_kid.say_2': ['Grandpa Omar the well-digger\ntold me.', 'Sand over water is just\na little bit cooler\nthan other sand!'],
    'events.kasim_kid.say_3': ['I climbed all the way down to the spring\'s\nbottom once! The bottom stone\nwas a little bit warm.', 'One of the guild camels wandered off\nto the southeast dunes. The grown-ups\nwere in a real fix.'],
    'events.kasim_rashid_memorial.say': ['...I hear you wrote about us\nin your Chronicle.', 'We\'ve carved our dead comrades\' names\nback onto the monument. Every one we remember.', 'What the war was for, I still can\'t\nremember. But who died --\nthat, I won\'t forget again.'],
    'events.kasim_zaid.say.0': 'Well, storyteller.\nRide the caravan cart? One night\nto the Sandedge waystation.',
    'events.kasim_zaid.i.choose': ['Ride (to Sandedge)', 'Not now'],
    'events.kasim_zaid.caption': 'After a night rocking in the cart,\nyou reach the Sandedge waystation.',
    'events.kasim_zaid.say': 'The caravan road\'s moving again.\nAll thanks to you.',
    'events.kasim_zaid.say_2': ['I\'m Zaid, master of the caravans.\nYou\'ve seen the notice?', 'We carry offerings to the Tomb Oasis.\nAn old custom. The old spring there\nis the source of our spring\'s water.', 'With sandstorms and bandits, we can\'t\nsend a caravan out. Would you guard us?\nThree nights of camp, to the oasis.'],
    'events.kasim_zaid.say_3': 'Ready?\nThe caravan\'s waiting outside the west gate.',
    'events.kasim_zaid.i.choose_2': ['Set out', 'Still preparing'],
    'events.kasim_zaid.i.choose.text': 'Set out with the caravan?',
    'events.kasim_zaid.say_4': 'All right. When you\'re ready,\ncome talk to me again.',
    'events.kasim_zaid.say_5': 'Right, we\'re off!\n...I\'m counting on you.',
    'events.kasim_arms.say': 'With the caravans back, I\'ve got some\ngood steel in. Take a look.',
    'events.kasim_arms.say_2': ['Hamid, arms seller.\nNo caravans coming, so my stock\'s\nall old stuff.', 'Desert monsters mostly have hard shells.\nBest keep a blunt weapon\nor two on hand.'],
    'events.kasim_shop_keeper.say': 'Welcome.\nGuild customers get ten percent off.',
    'events.kasim_shop_keeper.say_2': 'Welcome.\nIf you\'re crossing the desert, take plenty\nof medicine and earth stones.',
    'events.kasim_inn_keeper.say': ['Welcome to the "Star of the Spring."', 'Rest until the morning bell? Or until lights-out?\n...At lights-out, you can see\nstrange things in the desert.'],
    'events.kasim_inn_keeper.i.choose.0': 'Stay the night ({price} G)',
    'events.kasim_inn_keeper.i.choose.1': 'Rest until lights-out ({price} G)',
    'events.kasim_inn_keeper.i.choose.2': 'Not now',
    'events.kasim_inn_keeper.caption': 'Lights-out. Outside the window,\na great moon turns the sand white.\n...Tonight the moon is full.',
    'events.kasim_inn_keeper.caption_2': 'Lights-out. The town\'s lamps went dark.\nOut in the middle of the desert,\na row of lights shimmers...',
    'events.kasim_inn_keeper.say_2': 'Good morning. ...Not that\nthe sky\'s any different.',
    'events.kasim_inn_guest.say': ['I came down the road from the forest.\nThere\'s a waystation on the way, Sandedge.\nIts spring water is sweet.', 'A peddler girl named Lotta was\ncarrying some interesting wares.'],
    'events.kasim_inn_window.say': ['Outside the window, the desert at lights-out.\nBeyond the west gate, in the middle of\nthe sand, a row of lights shimmers.', '...The faint bustle of a market\ncan be heard.'],
    'events.kasim_inn_window.say_2': 'From the window, you can see the spring\nin the square. A golden fire shimmers\non its surface.',
    'events.kasim_inn_window.say_3': 'From the window, you can see the spring\nin the square. It\'s so shallow\nthe bottom shows through.',
    'events.kasim_tavern_master.news.0': ['Welcome to the Hourglass.\nAn hourglass is the only thing\nthat keeps time around here.', 'The sundial? That\'s just decoration.\nIt doesn\'t cast a shadow.'],
    'events.kasim_tavern_master.news.1': ['The lighthouse in the port town\'s lit again,\nthey say. The forest\'s Millennial Tree shone, too.', '...Hope our spring\'s\nnext in line.'],
    'events.kasim_tavern_master.news.2': ['In the snow village up north, they carry\nthe Bonfire Festival\'s fire up the peak, I hear.', 'And in the eastern marsh, bells ring in\nthe fog. ...Is the world starting\nto change, I wonder?'],
    'events.kasim_tavern_master.say': ['To celebrate the spring coming back,\nfirst drink\'s on the house tonight!', '...To King Hazar. A fine name.\nI won\'t forget it.'],
    'events.kasim_tavern_poster.say': ['A poster: "Bounty on the leader\nof the Sand Hawks."', 'In the corner, someone has added\nin small letters:\n"Give him a little more time."'],
    'events.kasim_tavern_poster.say_2': ['A poster: "Bounty on the leader of the\nSand Hawks." A drawing of a man\nwith a cloth-covered face.', '"Wields a scimitar. Travels with archers."'],
    'events.kasim_rumor_a.say': ['Up in the rocky ground to the north,\nsome caravan folk saw a rock move!', 'Its scales shone like a rainbow, they said.\nI\'d love to see a lizard like that.\n...No, actually, too scary.'],
    'events.kasim_rumor_b.say': ['Have you heard Nadia sing?\nThe king\'s song, with the name in it.', 'I can play along on my harp\nnow, too.'],
    'events.kasim_rumor_b.say_2': ['I\'m a traveling musician.\nNadia\'s song of the king is\nthis town\'s treasure.', '...Only the name, no one can sing.\nNot even me.\nThe score has nothing written there.', 'In the Ashen Wastes to the south, the\nfirebird\'s egg is growing cold, I hear.\nThe whole world\'s just getting colder.'],
    'events.kasim_rumor_c.say': ['I came from Yule, the snow village\nto the north. They\'re busy getting\nready for the Bonfire Festival.', 'Only, the villagers were worried\nthat the solstice fire is weak\nthis year.'],
    'events.kasim_caravan_man.say': 'With the signal fires back, we can run\nthe caravan road even at night.\nI should thank Tadeo.',
    'events.kasim_caravan_man.say_2': ['Travel with a caravan and monsters\ncome at you more. They smell\nthe water and the cargo.', 'In the sandstorm hollow, they say there\'s\na lizard with scales like gems. So quick\non its feet, nobody\'s ever caught one.', '...Stealing from it\'s another matter.'],
    'events.kasim_abul.say': ['The king\'s name has returned to\nthe evening prayers. The long duty of\nthe tomb\'s keeper is rewarded at last.', 'Take good care of the Sand King\'s Seal.'],
    'events.kasim_abul.say_2': ['I\'m Abul, keeper of the tomb.\nMy family has guarded the Nameless\nKing\'s tomb for generations.', 'Last year a Recorder came from the capital.\nCopied the stone tablet in the king\'s chamber\nonto paper. Since then, I can\'t recall his name.', 'The king\'s name is carved, one letter each,\non the pedestals of the guardian statues.\nPut all three together and it\'s his name.'],
    'events.kasim_abul.say_3': ['The king commands lamps of sun and moon.\nWhile the lamps burn, they say, his body\nis shielded by a veil of light.', 'Put out the lamps first.\n...And when the king\'s bandages unravel,\ncall him by his name.'],
    'events.kasim_abul_altar.say.0': 'A small altar.\nDried flowers and a cup of water.',
    'events.kasim_abul_altar.say.1': 'On the prayer tag, in fresh letters,\nsomeone has added: "To King Hazar."',
    'events.kasim_abul_altar.say.1_2': 'The prayer tag reads only "To King --."\nThe place for the name is empty.',
    // ---- src/events/desert_places.js
    'events.desert_world_pilgrim.say': ['The sky over Kasim way is\nfaintly golden.', 'The "daybreak" I\'ve been waiting for --\nmight it be a color like that?'],
    'events.desert_world_pilgrim.say_2': ['I\'m a pilgrim waiting for "daybreak."\nMy grandmother\'s grandmother spoke of it.', 'What daybreak is, I don\'t know.\n...But I make sure not to forget\nto wait for it.'],
    'events.desert_world_pilgrim.say_3': 'Take this, traveler.\nDesert nights are cold.',
    'events.desert_world_oil.say': 'With the signal fires back, the night roads\nare easier. Give my regards to Tadeo\nof the guild.',
    'events.desert_world_oil.say_2': ['I haul oil from the black spring.\nThe pass to the Ashen Wastes collapsed,\nso I\'m stuck in Kasim.', 'Did you see all three signal towers on the\ncaravan road are dark? Tadeo of the\nguild\'s at his wits\' end.'],
    'events.desert_mirage_empty.say': ['A flat stretch of sand, in the lamplit hours.\nNothing remains of the market.', 'A few camel tracks in the sand...\nthat end halfway.'],
    'events.desert_mirage_empty.say_2': ['A flat spot in the middle of the sand.\nThere\'s nothing here.', '...You\'ve heard that lights\nshimmer here at lights-out.'],
    'events.desert_temple_sand.say.0': 'The tops of strange pillars\njut out of the sand.',
    'events.desert_temple_sand.say.1': 'The sand is slowly drawing back.\n...On a full-moon night, the entrance\nmight show. (Lights-out {n}/3)',
    'events.desert_temple_sand.say.1_2': 'The sand around the pillars is hard.\nNothing like an entrance can be seen.',
    'events.sandedge_arrive.caption': 'The Sandedge waystation.\nA caravan inn at the roots of a great\npetrified tree, where the forest ends.',
    'events.sandedge_notice.say.0': 'The waystation\'s notice board.',
    'events.sandedge_notice.say.1': '"Eastern pass closed by an ash slide.\nThose bound for the Ashen Wastes, please\nwait until it is cleared."',
    'events.sandedge_notice.say.2': '"Those bound for the northern snowfields:\ndo not forget protection from the cold."',
    'events.sandedge_notice.say.2_2': '"Kasim\'s spring is dwindling.\nTop up your water at the waystation."',
    'events.sandedge_innkeeper.say': 'Welcome to the Sandedge inn.\nOur well water is sweet, and we\'re proud of it.',
    'events.sandedge_innkeeper.i.choose': ['Stay the night', 'Not now'],
    'events.sandedge_shop.say': 'The counter. Everything you\nneed for the road.',
    'events.sandedge_stable.say': 'A cart\'s leaving for Kasim.\nWant a ride?',
    'events.sandedge_stable.i.choose': ['Ride (to Kasim)', 'Not now'],
    'events.sandedge_stable.caption': 'After a night rocking in the cart,\nyou reach Kasim, the oasis town.',
    'events.sandedge_stable.say_2': ['I look after the camels.\nNo caravans going out, so the camels\nare bored stiff.', 'Carts used to run to Kasim\nevery night, once.'],
    'events.sandedge_forest_traveler.say': ['I came from the forest. Since the Millennial\nTree\'s crown lit up, nobody gets lost\non the forest paths anymore.', 'I came to trade forest resin\nfor desert salt.'],
    'events.sandedge_forest_traveler.say_2': ['I came through the northern forest.\n...Kept ending up back in\nthe same spot, over and over.', 'In the village of Fern, they were in an\nuproar over woodcutters who didn\'t come home.'],
    'events.sandedge_ash_traveler.say': ['I\'m a soldier from the Ashen Wastes, last\nto cross the pass before it collapsed.', 'In Caldera, the chief\'s holding a tournament\nto stop the firebird\'s egg\nfrom going cold, I hear.'],
    'events.sandedge_well_girl.say': 'The well water\'s colder and sweeter\nthan before! I wonder if it\'s connected\nto Kasim\'s spring.',
    'events.sandedge_well_girl.say_2': ['This well\'s water -- no matter\nhow tired you are, one cup\nperks you right up.', 'It\'s true. Try some!\n(The well is a healing spring.)'],
    'events.sandedge_rumor.say': ['Sad, of the caravans.\nI was walking the desert at lights-out,\nand there was a market in the middle of the sand.', 'When I got close, it vanished.\n...Rest at Kasim\'s inn until lights-out.\nYou might see it.'],
    'events.sandedge_bard.say': ['The port\'s lighthouse, the forest\'s\nMillennial Tree... Each time a Beacon\nreturns, there\'s one more song.', 'Where will the next one come from?'],
    'events.sandedge_bard.say_2': ['I collect songs of the roads.\nSongs of forest, desert, and ash.', '...Every one of them is missing a piece\nsomewhere. Strange, isn\'t it?'],
    'events.desert_mirage_arrive.caption': 'On the sand, rows of lights and the\nbustle of a market shimmer.\n...The voices sound a little far away.',
    'events.desert_mirage_seller.say': '...Tonight, I have nothing to sell.',
    'events.desert_mirage_seller.say_2': '...That item is already yours.\nThe market on the sand never sells\nthe same thing twice.',
    'events.desert_mirage_seller.say.0': '...This is "{name}."',
    'events.desert_mirage_seller.i.choose.0': 'Buy ({price} G)',
    'events.desert_mirage_seller.i.choose.1': 'Not now',
    'events.desert_mirage_seller.say_3': '...Not enough gold dust.',
    'events.desert_mirage_seller.say_4': '...As the Beacons return, the market\'s wares\nchange too. Come again at lights-out.',
    'events.desert_mirage_elder.say.0': 'This market is a market from King Hazar\'s day.\nThe year the king called the water, every\ncaravan in the desert gathered here.',
    'events.desert_mirage_elder.say.1': 'The sand remembers that bustle.\nAt lights-out, it recalls it.',
    'events.desert_mirage_elder.say.2': '...With the king\'s name back,\neven the sand seems glad.',
    'events.desert_mirage_elder.say.2_2': '...Since no one calls the king\'s name\nanymore, the market has grown faint.',
    'events.desert_mirage_child.say': ['Where did you come from?\nI\'ve always been here.', 'Have you ever seen the sun?\nI have. ...I think.'],
    'events.desert_mirage_dancer.say.0': '"Your name is Hazar, friend of the sun."\nOh, you know this\nsong too?',
    'events.desert_mirage_dancer.say': ['"O king who called water to the sea\nof sand"... The name? Heh...', 'When there\'s no one left to call it,\na name melts away into the sand.'],
    'events.desert_mirage_obelisk.say': ['A stone pillar at the market\'s north end:\n"Caravan Market -- in the Reign of the Sun King."', 'The pillar casts a sharp shadow\non the sand. ...Though the only\nlights are in front of it.'],
    'events.desert_hawks_arrive.caption': 'From deep in the cave, a hawk whistle\nsounded. ...The lookout has spotted you!',
    'events.desert_hawks_arrive.caption_2': 'The cave lookout raised a hand.\n"Guest of the chief. Go on through."',
    'events.desert_hawks_arrive.caption_3': 'The cave lookout eyed you.\n"Pay what\'s owed, and you can pass."',
    'events.desert_hawks_sentry.say': ['...Halt. This is the Sand Hawks\' nest.\nNo strange faces get through.', 'If you\'ve business with the chief, you\'ll\nfind him on the caravan road.\n...Behind a caravan carrying water.'],
    'events.desert_hawks_member.lines.hawk_door': 'The chief\'s guest. Make yourself at home.\nThough we\'ve only the water\nyou shared with us.',
    'events.desert_hawks_member.lines.hawk_door_2': 'You paid, so you can pass.\n...Don\'t get any funny ideas.',
    'events.desert_hawks_member.lines.hawk_cook': 'I heard you wrote about us\nin your Chronicle.\n...Thank you.',
    'events.desert_hawks_member.lines.hawk_cook_2': 'There are children and old folk in the caves.\nThere\'s never enough water.',
    'events.desert_hawks_member.lines.hawk_guard_l': 'When talk turns to twenty years ago,\nthe chief goes quiet. ...So do we.',
    'events.desert_hawks_member.lines.hawk_guard_r': 'The townsfolk call us bandits.\n...Well, they\'re not wrong.',
    'events.desert_hawks_member.say': '...This is the Sand Hawks\' nest.',
    'events.desert_hawks_old.say': ['I\'m an old soldier of the Sun Alliance.\nI still dream of the night\nof the champions\' bout.', 'I heard singing. From the enemy\'s lines.\nThe firebird\'s song, it was. ...No,\nwhose song it was, I can\'t recall.'],
    'events.desert_hawks_old.say_2': 'An old soldier\'s charm.\nI\'ve no more need of it.',
    'events.desert_hawks_shop.say': 'Black market. ...You\'re not one\nof us, so it\'s half again the price.',
    'events.desert_hawks_shop.say_2': 'Black market. For the chief\'s guest,\nI\'ll sell at town prices.',
    'events.desert_hawks_water.say.0': 'Large water jars stand in a row.\nWater taken from the caravans.',
    'events.desert_hawks_water.say.1': '...Marks for the water that was shared\nwith them are carved into the wall,\none by one.',
    'events.desert_hawks_water.say.1_2': 'On the wall, tallies of who drank\nhow many cups are carved and counted.',
    'events.desert_hawks_bunks.say': ['On the wall of the sleeping quarters\nis a child\'s scribble.', 'A hawk... and a big, round,\nshining thing. It\'s labeled\n"the sun."'],
    'events.desert_hawks_memorial.say': ['A new stone monument in the chief\'s hall:\n"The Sand Hawks -- Soldiers of the Sun."', 'The names of fallen comrades are\ncarved one by one, with\ngreat care.'],
    'events.desert_hawks_map_table.say': ['A map of the desert is spread out\non the table. The caravan road\nis dotted with marks.', 'In the corner is a sketch of the old\nbattlefield in the Ashen Wastes.\nThe Broken Sword Monument...?'],
    'events.desert_hawks_rashid.say': ['...A loss is a loss.\nWe won\'t raid caravans anymore.', '...Your Chronicle, was it? If you\'re\nwriting about us, just\ncall us bandits.'],
    'events.desert_hawks_rashid.say_2': ['Good of you to come. For the water.\nTake these.', 'One\'s my gloves.\nA thief\'s knack is soaked into them.', 'The other\'s a treasure map of the old\nbattlefield in the ash. ...I don\'t have\nthe legs to go back there.'],
    'events.desert_hawks_rashid.say.0': '...A guest who paid what was owed.\nI\'ll at least hear you out.',
    'events.desert_hawks_rashid.say.1': 'If you want my gloves, it\'s\n{price} G. A thief\'s knack is\nsoaked into them.',
    'events.desert_hawks_rashid.i.choose.0': 'Buy ({price} G)',
    'events.desert_hawks_rashid.i.choose.1': 'Not now',
    'events.desert_hawks_rashid.say_3': '...Not enough. Come back later.',
    'events.desert_hawks_rashid.say_4': '...Deal.',
    'events.desert_hawks_rashid.say_5': ['I hear the spring\'s back.\n...King Hazar, eh.', 'I envy a king who can sleep once his\nname is called. Our war\nhas no name.'],
    'events.desert_hawks_rashid.say_6': ['If you\'re going to the tomb, rest once\nbefore the king\'s chamber. The king there\ncommands lamps of sun and moon.', '...My grandfather said he fought\nfor the king\'s fire.'],
    'events.desert_hawks_boss.say': ['...So you\'ve come. Caravan dogs.\nThis is our last nest.', 'This time, I won\'t hold back!'],
    'events.desert_hawks_boss.say_2': ['...I yield.\nWe\'ve lost.', 'Take these gloves.\n...I\'m done with stealing.\nI\'ll find another way to feed our people.'],
    'events.desert_rocks_watcher.say': ['I\'m a scholar who watches lizards.\nI study the diamond lizard.', 'Its scales are harder than diamond.\nEven if you defeat it, the scales\nshatter and you get nothing.', 'So stealing is the only way.\n...It\'s quick to flee, so\nyour first move decides it all.'],
    'events.desert_rocks_scales.say': ['In a crack in the rocks lie fragments\nof rainbow-colored scale.', 'When you try to pick them up, they crumble\nlike sand between your fingers.'],
    'events.desert_oldcamp_arrive.caption': 'In the lee of the rocks, out of the sandstorm,\nan old campsite. The tents are torn,\nthe cargo half buried in sand.',
    'events.desert_oldcamp_notes.say': ['On a scrap of board stuck in the sand,\nsomething is written.', '"Stormy night. A row of lights toward the tomb.\nThey vanished as we neared. A market\'s voices."'],
    'events.desert_wellroom_keeper.say': 'My, you look thirsty.\nHave a drink from this well.',
    'events.desert_wellroom_keeper.caption': 'The cold well water\nquenched your thirst.',
    'events.desert_wellroom_keeper.say_2': ['This well\'s a resting place for caravans\ntaking the long way. I\'m its keeper.', 'Even when the spring runs low, this well\nnever dries. "King Hazar\'s well,"\nmy grandmother called it.'],
    'events.desert_wellroom_journal.say': ['The well keeper\'s logbook.\nThe names of caravans that rested here.', 'From the winter twenty years ago,\nthe entries suddenly thin out.'],
    'events.desert_temple_arrive.caption': 'Beneath the sand, an entire temple\nlay sleeping. The sun-wheel crest\nis carved into its pillars.',
    'events.desert_temple_door.say.0': 'A heavy door bearing the sun-wheel crest.\nIt has three round grooves.',
    'events.desert_temple_door.say.1': '{n, plural, one {# groove is glowing.} other {# grooves are glowing.}}\nThere were golden plates in the west and east\nside rooms, and the northwest room...',
    'events.desert_temple_claim.say': ['A monument of the Sunheir people.', '"The sun-fire is a piece of the sun.\nThe king took it from the sky and entrusted\nit to the spring. We are the sun\'s heirs."'],
    'events.desert_temple_claim.say_2': '...On the back of the monument, in small letters:\n"The king gave up his name.\nHe did not take it."',
    'events.desert_temple_disk.say': ['A golden disc at the back of the altar.\nIt seems it was hung in the sky to catch light.', 'The disc is cold,\nand reflects nothing.'],
    'events.desert_temple_guard.say': ['On either side of the inner sanctum,\nstone statues opened their eyes.', '"Those who are not heirs of the sun\nshall not pass --"'],
    'events.desert_temple_guard.caption': 'The statues crumbled, and the way\nto the altar opened.',
    // ---- src/events/desert_quests.js
    'leads.q_kasim_indigo.title': 'Indigo Cloth for Mother',
    'leads.q_kasim_indigo.from': 'Laila the indigo dyer',
    'leads.q_kasim_indigo.dir': 'North forest',
    'leads.q_kasim_indigo.text': 'Laila, an indigo dyer in Kasim, asked\nme to take indigo cloth to her mother\nin Yarrow, the hidden forest village.',
    'items.k_desert_indigo.name': 'Indigo Cloth',
    'items.k_desert_indigo.desc': 'Indigo cloth dyed by Laila.\nTo be delivered to her mother in Yarrow.',
    'ev.desert_quests.laila_mother.name': 'Old Indigo Dyer',
    'events.kasim_nadia.say': ['I wrote down the king\'s song.\nHere\'s a copy for you too.', 'This time, so I won\'t forget the name.\nI write it, sing it, and write it again.'],
    'events.kasim_nadia.say_2': 'I wonder if other towns have songs\nwith missing names. ...Someday\nI\'d like to go and hear them.',
    'events.kasim_nadia.say_3': '"Your name is Hazar, friend of the sun."\nHeh, no matter how many times I sing it,\nmy heart feels so light.',
    'events.kasim_nadia.say.0': 'I\'m Nadia. A dancer.\nEvery night I sing and dance the king\'s\nsong in the square. Listen.',
    'events.kasim_nadia.say_4': ['...Only the part with the name,\nI just can\'t sing. Not my mother,\nnot my grandmother either.', 'I heard the king\'s name was carved\nin the stones of the tomb.\nNobody can go and read it, though.'],
    'events.kasim_nadia.say_5': 'Thank you for my anklet bell!\nEvery time I dance, it goes\n*shalla*. Can you hear it?',
    'events.kasim_nadia.say.0_2': 'My anklet bell!\nYou found it!?',
    'events.kasim_nadia.say_6': ['This is the other one.\nKeep it, so we match.', 'Ring it when you run,\nand your feet feel lighter.'],
    'events.kasim_nadia.say_7': ['And, um... I\'m in trouble.\nI lost one of my silver\nanklet bells.', 'Someone saw a market kid pick it up.\nBut it seems they won\'t give it back\nfor nothing.'],
    'events.kasim_nadia.say_8': 'The market kid should have my anklet bell.\nThat kid\'s got a real sweet tooth.',
    'events.kasim_child.say': 'Nadia was dancing at the spring!\nHer anklet bell was jingling!',
    'events.kasim_child.say_2': 'The dates were yummy!\nBring some more, okay?',
    'events.kasim_child.say_3': 'I found a pretty bell that\ngoes jingle-jingle.\n...You can\'t have it!',
    'events.kasim_child.say_4': 'Wow, dates!\n...Oh, all right.\nI\'ll trade you the bell.',
    'events.kasim_child.say_5': ['This bell? I know\nit\'s Nadia\'s.', 'But I won\'t give it back for free.\nI\'ll trade it for dates,\nthough!'],
    'events.kasim_dates.say': 'With the spring back, the date palms\nwill perk up too.',
    'events.kasim_dates.say_2': 'Dates for sale.\nDried ones are sweet and keep well.',
    'events.kasim_dates.i.choose.0': 'Buy ({price} G)',
    'events.kasim_dates.i.choose.1': 'Not now',
    'events.kasim_dates.say_3': 'You\'re a bit short, dear.',
    'events.kasim_dates.say_4': 'Thank you kindly. The market kids\'\nfavorite treat.',
    'events.kasim_digger.say': 'The town\'s spring is back. I wonder if\nthe spring I dug helped even a little.',
    'events.kasim_digger.say_2': 'That little spring\'s become a fine\nresting spot for travelers, I hear.',
    'events.kasim_digger.say_3': ['Water came up?! Well done!', 'It\'s only a small spring, but now there\'s\nsomewhere to rest outside town.\nHere\'s my thanks. Take it.'],
    'events.kasim_digger.say_4': 'In the sand south of town, there are\nthree mounds. Dig there. The sand\nover water is a little cooler.',
    'events.kasim_digger.say_5': ['I\'m Omar the well-digger.\nThe town\'s wells and spring keep dwindling,\nso I\'m hunting for a new vein of water.', 'But with this back of mine...\nWould you try digging three spots\nin the sand south of town?'],
    'events.kasim_digger.i.choose': ['Accept', 'Not now'],
    'events.kasim_digger.say_6': 'I\'m counting on you. I\'ll lend you this spade.\nOut the south gate... no, out the west gate\nand round to the sand to the south.',
    'events.desert_dig.say': 'The sand is slightly mounded here.\nToo hard to dig by hand.',
    'events.desert_dig.say_2': 'Water wells up steadily\nfrom the hole you dug.',
    'events.desert_dig.say_3': 'Already dug here.',
    'events.desert_dig.say_4': ['As the spade goes in, the sand is\ncool and damp.', 'Dig deeper, and...\nwater bubbles up!'],
    'events.desert_dig.caption': 'A small spring has formed.\nBetter tell Omar.',
    'events.desert_dig.say_5': ['Nothing but dry sand.', '...A few old copper coins\nturned up at the bottom.'],
    'events.desert_dig.say_6': 'Nothing but dry sand.\nNo sign of water.',
    'events.kasim_guild_clerk.say': 'With the caravan road back, I can barely\nkeep up with the ledgers.',
    'events.kasim_guild_clerk.say_2': 'The camel\'s doing well.\nThank you so much.',
    'events.kasim_guild_clerk.say_3': ['You brought the camel back!\nThis one\'s so stubborn, won\'t budge\nuntil it sees the brand...', 'Here\'s a reward from the guild.'],
    'events.kasim_guild_clerk.say_4': 'The camel was seen around the dunes\nto the southeast.\nIt bears the guild\'s brand.',
    'events.kasim_guild_clerk.say_5': ['This is the Caravan Guild counter.\n...We have a problem. One of the guild\'s\ncamels has gone astray.', 'Someone says they saw it in the dunes\nto the southeast. Could you bring\nit back for us?'],
    'events.desert_camel_world.say': ['A camel with the guild\'s brand.\nIt\'s lazily chewing grass in the\nshade of a dune.', 'When you show it the reins, the camel\nsnorts and gets to its feet.'],
    'events.desert_camel_world.caption': 'The camel tagged along\nat the end of the line.',
    'events.desert_camel_world.caption_2': 'The camel is following you.\nTake it back to Kasim\'s Caravan Guild.',
    'events.kasim_tadeo.say': 'Carts run at night now, guided by\nthe signal fires. As a guildsman,\nnothing could make me happier.',
    'events.kasim_tadeo.say_2': 'The signal fires are back. On behalf\nof the Lampkeepers\' Guild, thank you.',
    'events.kasim_tadeo.say_3': ['All three lit again!\nYou can see the caravan road even at night.', 'Here\'s the guild\'s thanks.\nA mirror to reflect the signal fire.'],
    'events.kasim_tadeo.say_4': 'Three signal towers along the caravan road.\n{p0} to go. Pour the oil jar into\nthe tower\'s fire dish.',
    'events.kasim_tadeo.say_5': ['Hello -- did we meet in the port?\nTadeo, of the Lampkeepers\' Guild.\nI came all this way to sell oil.', 'All three signal towers on the caravan\nroad have gone out. The oil\nnever reached them.', 'Would you pour this black-spring oil\ninto the towers? There are three\nalong the caravan road.'],
    'events.desert_beacon.say': 'A signal tower.',
    'events.desert_beacon.say_2': 'Black oil burns bright red\nin the signal tower\'s fire dish.',
    'events.desert_beacon.say_3': ['A signal tower of stacked stone.\nIts fire dish is empty and sooty.', '...With oil, it could be\nlit again.'],
    'events.desert_beacon.say_4': 'You pour black-spring oil into the\nfire dish and light it.',
    'events.desert_beacon.caption': 'The signal fire blazes up. ({n}/3)',
    'events.desert_beacon.caption_2': 'The oil jar is empty.\nBetter tell Tadeo.',
    'events.kasim_salt.say': 'Lotta\'s basket has more wares now, eh?\nShe\'s got a head for business.',
    'events.kasim_salt.say_2': ['You delivered it!\nLotta sent a thank-you gift and\na message... or, well,', 'I can\'t read her writing.\nNever mind -- here\'s your fee.'],
    'events.kasim_salt.say_3': 'The Sandedge waystation is north of town,\npartway along the road to the forest.\nLotta\'s on the east side of the courtyard.',
    'events.kasim_salt.say_4': ['Karim, the salt seller.\nWhite salt from the south beach.', 'I\'ve a favor to ask. Would you take\nthis parcel of salt to Lotta the peddler\nat the Sandedge waystation?'],
    'events.kasim_salt.i.choose': ['Accept', 'Not now'],
    'events.sandedge_lotta.say': ['Karim\'s salt! I\'ve been waiting.\nIt sells for a good price in the forest village.', 'As thanks, I\'ll add more to my basket.\nTake a look.'],
    'events.sandedge_lotta.say_2': ['I\'m Lotta, a peddler.\nI travel the roads of forest, desert,\nand ash with just one basket.', 'Like rare things?\nThen take a look.'],
    'events.sandedge_lotta.say_3': 'Kasim\'s spring is back, they say!\nDesert salt will sell high again.',
    'events.sandedge_lotta.say_4': 'Welcome. What\'ll it be today?',
    'ev.desert_quests.MAPS.k_tmap_3.pitch': 'A map of the Ashen Wastes.\nThere\'s a sealed door on the lower level\nbeneath the Broken Sword Monument.',
    'ev.desert_quests.MAPS.k_tmap_4.pitch': 'A map a merchant captain from the southern\nislands left behind. There\'s a drawing\nof a chapel sunk underwater.',
    'ev.desert_quests.MAPS.k_tmap_5.pitch': 'A map of the fog on the western sea.\nA ship graveyard of a hundred masts.\n...You\'d need a ship.',
    'ev.desert_quests.MAPS.k_tmap_6.pitch': 'A map too smudged to read.\nWith a star fragment, it can be read,\nthe previous owner said.',
    'events.kasim_mapmaker.say': ['Yaz, the mapmaker.\nI collect old treasure maps.', 'No readable maps right now.\n...Each time a Beacon returns,\nthe smudged lines grow readable.'],
    'events.kasim_mapmaker.say_2': 'No maps left to sell.\nYou\'ve bought them all.',
    'events.kasim_mapmaker.say.0': 'Yaz, the mapmaker.\nI collect old treasure maps.',
    'events.kasim_mapmaker.i.choose.0': 'Buy ({price} G)',
    'events.kasim_mapmaker.i.choose.1': 'Not now',
    'events.kasim_mapmaker.say_3': 'You\'re short on money.\nThe maps won\'t run away.',
    'events.kasim_mapmaker.say_4': 'Thank you. Where these maps lead,\nno one\'s ever been yet.\n...I hope someday I can go.',
    'events.kasim_mapshop_wall.say': ['A wall-sized map of the desert.', 'North, the Sandedge waystation and the rocks.\nWest, the rocky mesa. Southwest, the\ncaravan road and its three camps.', 'Near the southern beach, someone has\nwritten in small letters: "Pillars?"'],
    'ev.desert_quests.FORTUNE.0.1': 'At lights-out, a row of lights appears\nin the middle of the sand...\nRest at the inn until lights-out.',
    'ev.desert_quests.FORTUNE.1': 'The southern beach... on a full-moon night,\npillars rise from the sand.\nAfter three lights-outs.',
    'ev.desert_quests.FORTUNE.2.1': 'In the rocks to the north, a rainbow glint...\nA light that flees is best stolen.',
    'ev.desert_quests.FORTUNE.3.1': 'From the western mesa, a hawk whistle...\nIn a cave south of the mesa lies something.',
    'ev.desert_quests.FORTUNE.4.1': 'A light midway along the northern road...\nAn inn of sweet water.',
    'events.kasim_fortune.say.0': '...Welcome.\nLet me read the road ahead\nas the sand reflects it.',
    'events.kasim_fortune.i.choose.0': 'Have your fortune told ({price} G)',
    'events.kasim_fortune.i.choose.1': 'Not now',
    'events.kasim_fortune.say': '...It seems you lack the fee.',
    'events.kasim_fortune.say_2': ['...The sand has nothing more to tell.\nYou know this desert well\nalready.', 'No fee is needed.'],
    'events.kasim_bazaar.say': 'Welcome! To celebrate the spring,\nI\'m feeling generous today.',
    'events.kasim_bazaar.say_2': 'Welcome. Stones, charms --\nI\'ve got them all.',
    'events.kasim_bazaar.opts': ['Browse', 'Not now'],
    'events.kasim_bazaar.opts_2': ['Browse', 'Haggle', 'Not now'],
    'events.kasim_bazaar': 'Haggle',
    'events.kasim_bazaar.say_3': 'Oho, you want to haggle, do you?\nLook me in the eye and strike\nthe deal at just the right moment!',
    'events.kasim_bazaar.r.title': 'Haggling',
    'events.kasim_bazaar.say_4': 'You got me, you got me!\nFor you, it\'s fifteen percent\noff from now on.',
    'events.kasim_bazaar.say_5': 'Ha ha, not good enough yet.\nCome challenge me again.',
    'events.kasim_yura_dyer.say': 'I read Mother\'s letter every night.\n"The forest fireflies are back," she says.',
    'events.kasim_yura_dyer.say_2': ['You met my mother!\n...Was she well?\nI\'m so glad...', 'As thanks, have this headcloth\nI dyed. It\'ll keep the sand off.'],
    'events.kasim_yura_dyer.say_3': 'Mother lives in the western house\nof Yarrow, the forest village.\nPlease take her the indigo cloth.',
    'events.kasim_yura_dyer.say_4': ['I\'m Laila. I came from Yarrow, the forest\nvillage, to train in indigo dyeing.', 'I want to send my mother cloth I dyed.\nIt might be the last cloth dyed\nwith the spring\'s water.'],
    'events.kasim_yura_dyer.i.choose': ['Accept', 'Not now'],
    'events.desert_yura_mother.say': 'I wonder if Laila\'s doing well.\n...That girl\'s indigo is the color of the sky.',
    'events.desert_yura_mother.say_2': 'My daughter went off to a desert town\nto train. Her letters are so few.',
    'events.desert_yura_mother.say_3': '{hero} handed over Laila\'s indigo cloth.',
    'events.desert_yura_mother.say_4': ['Oh my... it\'s Laila\'s indigo.\nShe can bring out such a deep\ncolor now.', 'Thank you. Tell my daughter for me:\nher mother is well.'],
    // ---- src/events/desert_tomb.js
    'ev.desert_tomb.HAZAL.name': 'Nameless Sand King',
    'ev.desert_tomb.HAZAL2.name': 'Hazar',
    'ev.desert_tomb.GLYPH.ha.1': 'HA',
    'ev.desert_tomb.GLYPH.za.1': 'ZA',
    'ev.desert_tomb.GLYPH.ru.1': 'R',
    'events.desert_tomb_sealed.say': ['The tomb entrance is blocked by\ndrifted sand.', 'Too much to dig out by hand.\n...If only you had the caravan\'s tools.'],
    'events.desert_tomb_arrive.caption': 'The air is cool.\nThe torches on the walls are still burning --\nwho could have lit them?',
    'events.desert_tomb2_arrive.caption': 'The sand underfoot shifts now and then,\nas if flowing.\n...Somewhere, something is digging through it.',
    'events.desert_tomb3_arrive.caption': 'Just before the king\'s chamber.\nThe air is heavy.\nA voice is calling someone\'s name...',
    'events.desert_tomb_door.say.0': 'A heavy stone door carved with a golden seal.\nOn both sides are grooves of the same seal.',
    'events.desert_tomb_door.say.1': 'A light glows in one of the grooves.\n({p0} to go)',
    'events.desert_tomb_door.say.1_2': 'In the small rooms to the west and east,\nthere were pressure plates bearing\nthe same golden seal...',
    'ev.desert_tomb.desert_tomb_plate_w': ['The plate sank, and the golden seal\nlit up. (#)', 'In the distance, a heavy stone door\ncould be heard opening.'],
    'ev.desert_tomb.desert_tomb_plate_e': ['The plate sank, and the golden seal\nlit up. (#)', 'In the distance, a heavy stone door\ncould be heard opening.'],
    'ev.desert_tomb.plate': ['The sun-wheel plate lit up. (#)', 'The sun shines on all three plates.\nThe inner door opens.'],
    'events.desert_tomb_glyph.say': 'A guardian statue. On its pedestal, the spot\nwhere the letter "{p0}" was is slightly chipped.',
    'events.desert_tomb_glyph.say.0': 'A stern guardian statue.\nOld letters are carved into its pedestal.',
    'events.desert_tomb_glyph.say.1': '..."{p0}."\nOnly the stone around the letter is loose.',
    'events.desert_tomb_glyph.say_2': ['When you line up the three stone pieces,\nthey form a single name.', '"HA - ZA - R" --\n...Hazar.'],
    'events.desert_tomb_glyph.caption': 'You wrote the king\'s name in the margin\nof the Chronicle. (Use it in battle\nto call his name.)',
    'events.desert_tomb_glyph.say_3': '{n, plural, one {That\'s # name stone.} other {That\'s # name stones.}}',
    'events.desert_tomb_ghost.say': '...The king has regained his name.\nNow I, too, can finally sleep.',
    'events.desert_tomb_ghost.say_2': ['...You too have come seeking\nthe king\'s name?', 'There are three guardian statues.\nOne deep in the west of this floor.\nOne at the far west of the floor below.', 'The last is east of the king\'s chamber.\n...Meet the king without his name, and\nhe will want even yours.'],
    'events.desert_tomb_lizard.say': 'In a crack in the rocks lies\na shed lizard skin.',
    'events.desert_tomb_lizard.say_2': ['In a crack in the rocks, rainbow scales\nflashed.', '...A diamond lizard!'],
    'events.desert_tomb_quicksand.say': 'The quicksand has stopped.\nIt\'s just ordinary sand now.',
    'events.desert_tomb_quicksand.say_2': ['The sand is flowing in a swirl.\nStep in, and it\'ll swallow you.', 'Every time something moves deep beneath\nthe sand, the swirl grows stronger...'],
    'events.desert_tomb_robber.say': ['Ugh... water...', 'The quicksand\'s the sand burrower\'s doing...\nAs long as it keeps digging under the sand,\nthe quicksand won\'t stop.', 'Once it burrows... hitting or cutting\nwon\'t touch it.\nHit it with earth power, drag it out...'],
    'events.desert_tomb_robber.say_2': '{hero} shared a little water with him.',
    'events.desert_tomb_robber.say_3': 'Thanks...\nTake this. An earth stone.',
    'events.desert_tomb_robber_leave.say': 'The collapsed grave robber\nstaggered to his feet.',
    'events.desert_tomb_robber_leave.say_2': ['...The sound of the sand has stopped.\nYou took down that sand burrower...!', 'Thanks to the water you gave me,\nI think I can crawl home.\n...I won\'t forget this.'],
    'events.desert_tomb_robber_leave.say_3': ['...The sound of the sand has stopped.\nYou took down that sand burrower...!', '...I\'ve had it with tombs.\nI\'m going home while I still can.'],
    'events.desert_tomb_robber_leave.say.name': 'Grave Robber',
    'events.desert_tomb_robber_leave.caption': 'Dragging his leg, the grave robber\nheaded back up to the floor above.',
    'events.desert_tomb_worm.say': ['The sand underfoot heaved up!', 'A gigantic maw thrusts up\nout of the sand --!'],
    'events.desert_tomb_worm.caption': 'When the sand burrower collapsed,\nthe swirl of quicksand quietly stopped.',
    'events.desert_tomb_rubbing.say': ['A stone tablet carved with the king\'s deeds.\n...Paper fibers cling to its face, and\nfaint traces of ink remain.', 'Someone copied the tablet.\nWherever it was copied, the letters\nhave vanished from the stone.', 'A tag lay in the sand:\n"Archive Copy No. 82."'],
    'events.desert_tomb_throne.say': 'A soft golden light dwells\nin the crystal of the throne.',
    'events.desert_tomb_throne.say_2': 'The crystal beside the throne.\nIt has no light, clouded the color of sand.',
    'events.desert_tomb_king.say': 'Before the throne stands a great\nshadow wrapped in bandages.',
    'events.desert_tomb_king.say_2': '...My name...\nGive me back my name...!',
    'events.desert_tomb_king.caption': '(The king\'s name, written in the Chronicle\'s\nmargin, glows faintly.\nUse it in battle to call his name.)',
    'events.desert_tomb_king.say_3': ['Hearing his name called, the king slowly\nlowered the arm he had raised.', 'The bandages unraveled, and sand\ntrickled softly away...'],
    'events.desert_tomb_king.say_4': 'The Sand King fell to his knees,\nand sand spilled from beneath his bandages.',
    'events.desert_tomb_king.say_5': '...My name... someone...',
    'events.desert_tomb_king.say_6': '{hero} opened the Chronicle\nand wrote the king\'s name:\n"Hazar."',
    'events.desert_tomb_king.say_7': ['From the stone pieces and the traces of ink\nleft on the tablet, {hero}\nread out the king\'s name.', '{hero} opened the Chronicle\nand wrote the king\'s name: "Hazar."'],
    'events.desert_tomb_king.say_8': 'Hazar... yes.\nThat is my name.',
    'events.desert_tomb_king.say_9': 'So my people remembered\nour promise...',
    'events.desert_tomb_king.say_10': ['In exchange for water, I gave my name\nto the spirit of the sand.', 'While the name is called, the sun-fire shall\nnot die. ...That promise, too, was copied\nfrom the stone, and vanished.', 'Storyteller.\nGive my name back once more\nto the people of the spring.'],
    'events.desert_tomb_king.caption_2': 'In the margin of the Clue Journal,\na new line had appeared.',
    'events.desert_finale.caption': 'At the bottom of the old spring, a golden fire\nkindled. The sun-fire --\nwater wells up from the depths.',
    'events.desert_finale.say': ['The spring... the spring is filling!', '...This light -- it\'s the color of the\n"dawn star" in my grandmother\'s song.'],
    'events.desert_finale.say.name': 'Zaid',
    'events.desert_finale.caption_2': 'The night the caravan returned to Kasim,\nwater came welling up from the town\'s\nfailing spring.',
    'events.desert_finale.say.0': 'The spring...! Father, look!\nThe old writing on the bottom is glowing!',
    'events.desert_finale.say.name_2': 'Fara',
    'events.desert_finale.say_2': ['You learned the king\'s name, didn\'t you?\n...Tell me.', 'Hazar... Yes, it fits perfectly.\nI\'ll try singing it.'],
    'events.desert_finale.say.name_3': 'Nadia',
    'events.desert_finale.say_3': ['The whole square sang the king\'s name\nalong with Nadia.', 'To the evening prayers,\na name returned.'],
    'events.desert_finale.say_4': ['The sun-fire is a piece of the sun.\nKing Hazar brought it down from the sky.', '...So my grandfather used to say.\nThe Sun Alliance fought to\nprotect that fire.'],
    'events.desert_finale.say.name_4': 'Sundial Grandpa',
    'events.desert_finale.say_5': '{hero} opened the Chronicle.\nHow should this desert be written?',
    'events.desert_finale.i.choose': ['Write the Sand Hawks as "desert bandits"', 'Write the Sand Hawks as "survivors of the Sunheir War"'],
    'events.desert_finale.i.choose.text': 'What will you write in the Chronicle?',
    'events.desert_finale.say_6': '"The Sand Hawks were once soldiers who fought\nfor the king\'s fire. No one remembers\nwhat the war was for..."',
    'events.desert_finale.say_7': '"Bandits called the Sand Hawks attacked the\ncaravan, and the king took back his name..."',
    'events.desert_after.say': ['Storyteller. As keeper of the tomb,\nlet me thank you.', 'This is the Sand King\'s Seal, guarded by\ngenerations of tomb keepers. It\'s only right\nthat the one who called his name should hold it.'],
    'events.desert_after.say.name': 'Abul',
    'events.desert_after.say_2': ['Thanks from the Caravan Guild, too.\nFrom now on, your bill at Kasim\'s\nshops is ten percent off.', 'And you can ride the caravan cart\nanytime. One night gets you\nto the Sandedge waystation.'],
    'events.desert_after.say.name_2': 'Zaid',
    'events.desert_after.caption': 'Kasim\'s shops are now 10% cheaper.\nYou can now ride the caravan cart.',
    'events.desert_after.caption_2': '...Some days later, it\'s said, a masked man\nstood alone before the town\'s war memorial.',
    'events.desert_after.caption_3': '...Some days later, it\'s said, the Sand Hawks\ncame to carve their comrades\' names\nback onto the town\'s war memorial.',
    'events.desert_after.caption_4': 'Laila the indigo dyer said,\n"When the spring comes back,\nI want to tell my mother."',
    'events.desert_hazal_after.say': 'The white darkness has come as far as\nthe far side of the sand. ...Storyteller,\ndo not let go of your name.',
    'events.desert_hazal_after.say_2': ['The fire at the bottom of the spring burns by\nthe people\'s prayers. My name has returned\nto the evening prayers.', 'The fire will not die now.\n...Thank you, storyteller.'],
    'events.desert_hazal_after.say_3': ['How warm it is to be called by name.', 'The monsters in the king\'s chamber are beyond\neven my power to calm. They should serve\nwell to hone your skill.'],
    'events.desert_abul_oasis.say': 'A warm wind blows from\nthe king\'s chamber...',
    'events.desert_abul_oasis.say_2': ['You\'ve gathered all three letters.\n...Hazar. Yes, that is the king\'s name.', 'Call him by that name before him.\nWhen his name is called, the king\nwill still the sand\'s wrath.'],
    'events.desert_abul_oasis.say.0': 'On the pedestals of the tomb\'s guardian\nstatues, the king\'s name is carved\none letter at a time.',
    'events.desert_abul_oasis.say.1': '{n, plural, one {You hold # letter now.} other {You hold # letters now.}}\nWith all three, you\'ll have\nthe king\'s name.',
    'events.desert_abul_oasis.say.2': 'One is deep in the west of the entrance floor.\nOne at the far west of the floor below.\nOne east of the king\'s chamber.',
    'events.desert_abul_oasis.say_3': 'Take this with you.\nThe tomb keeper\'s incense, to ward off evil.',
    'events.desert_camp3_oldspring.say': ['At the bottom of the spring, a golden fire\nburns and flickers.', 'The water is clear and warm.'],
    'events.desert_camp3_oldspring.say_2': ['An old spring. The water barely\nreaches your ankles.', 'The middle of the bottom stone\nis faintly warm...\nlike the embers of a fire.'],
  });
})(window.RPG);
